CREATE OR REPLACE FUNCTION public.public_adoption_page(_slug text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('shelter',jsonb_build_object('id',s.id,'name',s.name,'slug',s.slug),'cats',coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'photo_url',c.photo_url,'breed',c.breed,'color',c.color,'age_years',c.age_years,'sex',c.sex,'temperament',c.temperament,'bio',c.bio,'tags',coalesce(c.tags,'{}')) ORDER BY c.created_at DESC) FROM public.cats c WHERE c.shelter_id=s.id AND c.stage='available'),'[]'::jsonb)) FROM public.shelters s WHERE s.slug=_slug $$;
REVOKE ALL ON FUNCTION public.public_adoption_page(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_adoption_page(text) TO anon,authenticated,service_role;
